/**
 * fizzbuzz - FizzBuzz funksiyasi
 * n soni berilganda 1..n sonlaridan Fizz, Buzz va FizzBuzz belgilanganlari
 */
export function fizzbuzz(n) {
  const result = [];
  for (let i = 1; i <= n; i++) {
    if (i % 3 === 0 && i % 5 === 0) {
      result.push('FizzBuzz');
    } else if (i % 3 === 0) {
      result.push('Fizz');
    } else if (i % 5 === 0) {
      result.push('Buzz');
    } else {
      result.push(String(i));
    }
  }
  return result.join(' ');
}

