export function fizzbuzz(n) {
  const result = [];
  for (let i = 1; i <= n; i++) {
    if (i % 3 === 0) {
      result.push('Fizz');
    }
    if (i % 5 === 0) {
      result.push('Buzz');
    }
    if (i % 3 === 0 && i % 5 === 0) {
      result.push('FizzBuzz');
    } else {
      result.push(i.toString());
    }
  }
